// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX, Log} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(uint256 v1, uint256 v2, address actor) public {
        vm.assume(actor != address(this) && actor != address(0));
        vm.startPrank(address(this));
        c.SetMinSum(v1);
        c.SetLogFile(address(new Log()));
        c.Initialized();
        vm.stopPrank();

        vm.prank(actor);
        bool ok;
        try c.SetMinSum(v2) { ok = true; } catch { ok = false; }

        assertTrue(!ok && c.MinSum() == v1);
    }
}
